'use client';

import * as React from 'react';
import { Heart } from 'lucide-react';

import { cn } from '@/lib/utils';
import { Avatar, AvatarImage, AvatarFallback } from '@/components/ui/avatar';
import { Text } from '@/components/ui/text';
import type { Comment } from '@/types/api';

// ============================================================================
// Type Definitions
// ============================================================================

export interface CommentItemProps {
  comment: Comment;
  onReply?: (commentId: string) => void;
  onLike?: (commentId: string, isLiked: boolean) => void;
  level?: number;
  className?: string;
}

// ============================================================================
// Sub-components
// ============================================================================

interface LikeButtonProps {
  isLiked: boolean;
  count: number;
  onClick: () => void;
}

function LikeButton({ isLiked, count, onClick }: LikeButtonProps) {
  return (
    <button
      onClick={onClick}
      className="flex flex-col items-center gap-1.5 w-10"
      aria-label={isLiked ? 'Unlike comment' : 'Like comment'}
    >
      <Heart
        className={cn(
          'size-5 transition-colors',
          isLiked
            ? 'fill-[#dc3e42] stroke-[#dc3e42]'
            : 'fill-none stroke-[#211f26]'
        )}
      />
      {count > 0 && (
        <Text className="text-sm font-medium text-foreground/60">{count}</Text>
      )}
    </button>
  );
}

interface RepliesToggleProps {
  repliesCount: number;
  isExpanded: boolean;
  onToggle: () => void;
}

function RepliesToggle({ repliesCount, isExpanded, onToggle }: RepliesToggleProps) {
  if (repliesCount === 0) return null;

  return (
    <button
      onClick={onToggle}
      className="flex items-center gap-1 text-sm font-medium text-foreground/60 hover:text-foreground transition-colors"
    >
      <div className="w-8 h-px bg-foreground/15" />
      <span>
        {isExpanded
          ? 'Hide replies'
          : `View ${repliesCount} more ${repliesCount === 1 ? 'reply' : 'replies'}`}
      </span>
    </button>
  );
}

// ============================================================================
// Main Component
// ============================================================================

function CommentItem({
  comment,
  onReply,
  onLike,
  level = 0,
  className,
}: CommentItemProps) {
  const [isExpanded, setIsExpanded] = React.useState(level === 0);

  const handleLike = React.useCallback(() => {
    onLike?.(comment.id, !comment.isLiked);
  }, [comment.id, comment.isLiked, onLike]);

  const handleReply = React.useCallback(() => {
    onReply?.(comment.id);
  }, [comment.id, onReply]);

  const toggleReplies = React.useCallback(() => {
    setIsExpanded((prev) => !prev);
  }, []);

  const hasReplies = comment.replies && comment.replies.length > 0;
  const showNestedReplies = isExpanded && hasReplies;

  return (
    <div className={cn('flex gap-2 w-full', className)}>
      {/* Avatar */}
      <Avatar className="size-8 shrink-0">
        <AvatarImage src={comment.author.avatarUrl} alt={comment.author.name} />
        <AvatarFallback>
          {comment.author.name
            .split(' ')
            .map((n) => n[0])
            .join('')
            .toUpperCase()
            .slice(0, 2)}
        </AvatarFallback>
      </Avatar>

      {/* Content */}
      <div className="flex-1 min-w-0 overflow-hidden">
        <div className="flex flex-col gap-1">
          {/* Header: Name & Timestamp */}
          <div className="flex items-center gap-1">
            <Text className="text-sm font-semibold text-foreground">
              {comment.author.name}
            </Text>
            <Text className="text-xs text-foreground/60">{comment.timestamp}</Text>
          </div>

          {/* Body: Content, Reply, Like */}
          <div className="flex gap-3">
            <div className="flex-1 flex flex-col gap-2">
              <Text className="text-sm text-foreground leading-5 whitespace-pre-wrap break-words">
                {comment.content}
              </Text>

              <button
                onClick={handleReply}
                className="text-sm font-medium text-foreground/60 hover:text-foreground transition-colors w-fit"
              >
                Reply
              </button>

              {/* Replies Toggle */}
              {(comment.repliesCount > 0 || hasReplies) && (
                <RepliesToggle
                  repliesCount={
                    hasReplies ? comment.replies!.length : comment.repliesCount
                  }
                  isExpanded={isExpanded}
                  onToggle={toggleReplies}
                />
              )}
            </div>

            {/* Like Button */}
            <LikeButton
              isLiked={comment.isLiked}
              count={comment.likesCount}
              onClick={handleLike}
            />
          </div>

          {/* Nested Replies */}
          {showNestedReplies && (
            <div className="flex flex-col gap-5 pt-5">
              {comment.replies!.map((reply) => (
                <CommentItem
                  key={reply.id}
                  comment={reply}
                  onReply={onReply}
                  onLike={onLike}
                  level={level + 1}
                />
              ))}
            </div>
          )}
        </div>
      </div>
    </div>
  );
}

export { CommentItem };
